<script setup>import{router}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';import Pagination from'../../Components/Pagination.vue';defineProps({configured:Boolean,config:Object,counts:Object,logs:Object});</script><template><AdminLayout><div class="flex justify-between"><div><p class="section-kicker">Channels</p><h1 class="section-title">Google Merchant</h1></div><div class="flex gap-2"><button class="btn-light" @click="router.post('/admin/merchant/test')">Test connection</button><button class="btn-primary" @click="router.post('/admin/merchant/sync-all')">Queue catalogue sync</button></div></div><div class="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><div class="metric-card"><p class="text-xs text-slate-500">Configured</p><b>{{configured?'Yes':'No'}}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Eligible</p><b>{{counts.eligible}}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Synced</p><b>{{counts.synced}}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Failed</p><b>{{counts.failed}}</b></div></div><div class="card mt-6 overflow-x-auto"><table class="admin-table"><thead><tr><th>Product</th><th>Action</th><th>Status</th><th>Time</th></tr></thead><tbody><tr v-for="l in logs.data" :key="l.id"><td>{{l.product?.name||'Connection test'}}</td><td>{{l.action}}</td><td>{{l.status}}</td><td>{{l.synced_at||l.created_at}}</td></tr></tbody></table></div><Pagination :links="logs.links"/></AdminLayout></template>
